CREATE OR REPLACE FUNCTION public.upgrade_enquiry_context(_firm_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE _org text; _email text; _clients jsonb; BEGIN PERFORM app_private.assert_aal2(); IF NOT public.me_can_manage_cards(_firm_id) THEN RETURN NULL; END IF; SELECT name INTO _org FROM public.firms WHERE id=_firm_id; IF _org IS NULL THEN RETURN NULL; END IF; SELECT email INTO _email FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL; IF _email IS NULL THEN RETURN NULL; END IF; SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name) ORDER BY name),'[]'::jsonb) INTO _clients FROM public.clients WHERE firm_id=_firm_id AND app_private.user_can_read_client(auth.uid(),id); RETURN jsonb_build_object('firmId',_firm_id,'organisation',_org,'email',_email,'clients',_clients,'advisory',coalesce((SELECT advisory_enabled OR (trial_advisory_enabled AND trial_ends_at>now()) FROM public.org_subscription_options WHERE firm_id=_firm_id),false)); END; $$; REVOKE EXECUTE ON FUNCTION public.upgrade_enquiry_context(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.upgrade_enquiry_context(uuid) TO authenticated; NOTIFY pgrst,'reload schema';